def siparis_raporu(db, siparisler):
    rapor = []
    for s in siparisler:
        ad = db.execute("SELECT ad FROM musteri WHERE id = ?", (s["musteri_id"],)).fetchone()
        rapor.append((s["id"], ad))
    return rapor

def yoklama(gelenler, kayit):
    kayitlilar = list(kayit)
    return [no for no in gelenler if no in kayitlilar]

def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

import time


def siparis_bekle(api):
    while True:
        if api.yeni_siparis_var_mi():
            return api.siparisi_al()
        time.sleep(0.1)

def eslestir(ogrenciler, dersler):
    eslesme = []
    for o in ogrenciler:
        for d in dersler:
            if d["ogrenci_id"] == o["id"]:
                eslesme.append((o["ad"], d["ad"]))
    return eslesme

def toplam_ciro(satislar):
    toplam = 0
    for _, satir in satislar.iterrows():
        toplam += satir["adet"] * satir["fiyat"]
    return toplam

