import numpy as np


def normalize(dizi):
    sonuc = np.zeros(len(dizi))
    for i in range(len(dizi)):
        sonuc[i] = (dizi[i] - dizi.mean()) / dizi.std()
    return sonuc

def yasakli_kelime_var_mi(mesajlar, yasakli_metin):
    sonuc = []
    for m in mesajlar:
        yasaklar = yasakli_metin.lower().split(",")
        sonuc.append(any(y in m for y in yasaklar))
    return sonuc

def kareler(n):
    toplam = 0
    for i in list(range(n)):
        toplam += i * i
    return toplam

